package dev.gustavopere.rpgskilltree.runtime;
import dev.gustavopere.rpgskilltree.core.CombatPerkNodeBinding;import dev.gustavopere.rpgskilltree.core.CombatPerkRanks;import dev.gustavopere.rpgskilltree.core.PassiveNodeProgress;import dev.gustavopere.rpgskilltree.core.ProgressionState;import java.util.LinkedHashMap;import java.util.Map;import java.util.Objects;import net.minecraft.resources.ResourceLocation;
public final class CombatPerkAvailabilityRuntime{private CombatPerkAvailabilityRuntime(){}public static boolean isAvailable(ResourceLocation id){Objects.requireNonNull(id);return CombatPerkNodeBinding.catalogCode(id.toString()).map(CombatPerkAvailabilityRuntime::isCatalogCodeAvailable).orElse(true);}public static boolean isCatalogCodeAvailable(String c){Objects.requireNonNull(c);return switch(c){case"A0042","A0044","A0047","A0048","A0050","A0052","A0053","A0054","A0067","A0072","A0075","A0077","A0080"->false;default->true;};}public static CombatPerkRanks effectiveRanks(CombatPerkRanks p){Objects.requireNonNull(p);Map<String,Integer>e=new LinkedHashMap<>();p.ranks().forEach((c,r)->{if(isCatalogCodeAvailable(c))e.put(c,r);});return e.isEmpty()?CombatPerkRanks.empty():CombatPerkRanks.of(e);}public static CombatPerkRanks effectiveRanks(PassiveNodeProgress p){Objects.requireNonNull(p);return effectiveRanks(CombatPerkNodeBinding.ranks(p));}public static ProgressionState effectiveAccessState(ProgressionState s){Objects.requireNonNull(s);Map<String,Integer>e=new LinkedHashMap<>(s.passiveNodes().ranks());e.entrySet().removeIf(x->CombatPerkNodeBinding.catalogCode(x.getKey()).map(c->!isCatalogCodeAvailable(c)).orElse(false));return s.withPassiveNodes(PassiveNodeProgress.of(e));}}
